keyframes.an1:
@keyframes an1 { 
  0% { transform: rotate(0deg); }
  5% { transform: rotate(3deg); }
  15% { transform: rotate(-2.5deg); }
  25% { transform: rotate(2deg); }
  35% { transform: rotate(-1.5deg); }
  45% { transform: rotate(1deg); }
  55% { transform: rotate(-1.5deg); }
  65% { transform: rotate(2deg); }
  75% { transform: rotate(-2deg); }
  85% { transform: rotate(2.5deg); }
  95% { transform: rotate(-3deg); }
  100% { transform: rotate(0deg); }
}

keyframes.pulse-orange:
@keyframes pulse-orange { 
  0% { transform: scale(0.999); box-shadow: rgb(250, 205, 134) 0px 0px; }
  70% { transform: scale(1); box-shadow: rgba(255, 121, 63, 0) 0px 0px 0px 10px; }
  100% { transform: scale(0.999); box-shadow: rgba(255, 121, 63, 0) 0px 0px; }
}

keyframes.snowfall:
@keyframes snowfall { 
  0% { opacity: 1; }
  65% { opacity: 1; }
  100% { opacity: 0; transform: translate(-120px, 100vh) skew(-10deg) rotateX(50deg) rotateY(50deg); }
}

keyframes.spx-fold-in:
@keyframes spx-fold-in { 
  0% { opacity: 0; transform: translateY(-6px); }
  100% { opacity: 1; transform: none; }
}

keyframes.slideIn:
@keyframes slideIn { 
  0% { opacity: 0; transform: translateY(-150%); }
  100% { opacity: 1; transform: translateY(-100%); }
}

keyframes.slideOut:
@keyframes slideOut { 
  0% { opacity: 1; transform: translateY(-100%); }
  30% { opacity: 0; }
  100% { opacity: 0; transform: translateY(-50%); }
}

keyframes.bounce:
@keyframes bounce { 
  0%, 100% { animation-timing-function: cubic-bezier(0.8, 0, 1, 1); transform: translateY(-25%); }
  50% { animation-timing-function: cubic-bezier(0, 0, 0.2, 1); transform: none; }
}

